baseline = {"PermitRootLogin": "no", "PasswordAuthentication": "no", "MaxAuthTries": "5"}
fleet = {
    "web-01": {"PermitRootLogin": "no", "PasswordAuthentication": "no", "MaxAuthTries": "5"},
    "web-02": {"PermitRootLogin": "yes", "PasswordAuthentication": "no", "MaxAuthTries": "5"},
    "batch-01": {"PermitRootLogin": "no", "PasswordAuthentication": "yes"},
}
for host, conf in fleet.items():
    bad = [k for k, v in baseline.items() if conf.get(k) != v]
    print(f"{host:<9} {'양호' if not bad else '취약 ' + ', '.join(bad)}")
# web-01    양호
# web-02    취약 PermitRootLogin
# batch-01  취약 PasswordAuthentication, MaxAuthTries

def apply(state, desired):
    changed = [k for k, v in desired.items() if state.get(k) != v]
    for k in changed:
        state[k] = desired[k]
    return changed

server = {"PermitRootLogin": "yes", "PasswordAuthentication": "yes", "ntp": "off"}
want = {"PermitRootLogin": "no", "PasswordAuthentication": "no", "ntp": "on"}
print("1st run changed:", apply(server, want))
print("2nd run changed:", apply(server, want))
# 1st run changed: ['PermitRootLogin', 'PasswordAuthentication', 'ntp']
# 2nd run changed: []
